-- Name: may_client_change_appointment(timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.may_client_change_appointment(p_starts_at timestamp with time zone, p_organization_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_starts_at > now() + make_interval(
    hours => coalesce(
      (select o.cancellation_notice_hours
         from public.organizations o
        where o.id = p_organization_id),
      12
    )
  );
$$;


