--
-- Name: my_org_ids(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.my_org_ids(p_slugs text[]) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct ur.organization_id
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  where ur.user_id = (select auth.uid())
    and ur.revoked_at is null
    and r.slug = any (p_slugs);
$$;


ALTER FUNCTION public.my_org_ids(p_slugs text[]) OWNER TO postgres;

--
-- Name: FUNCTION my_org_ids(p_slugs text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.my_org_ids(p_slugs text[]) IS 'The organizations the caller holds any of these roles in. Written for
   `organization_id in (select public.my_org_ids(...))`, which Postgres runs
   once per statement rather than once per row.';


--
-- Name: my_permission_org_ids(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.my_permission_org_ids(p_key text) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct ur.organization_id
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  join public.role_permissions rp on rp.role_id = r.id
  where ur.user_id = (select auth.uid())
    and ur.revoked_at is null
    and r.deleted_at is null
    and rp.permission_key = p_key;
$$;


ALTER FUNCTION public.my_permission_org_ids(p_key text) OWNER TO postgres;

--
-- Name: FUNCTION my_permission_org_ids(p_key text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.my_permission_org_ids(p_key text) IS 'The organizations the caller holds this permission in, through any role.';


--
-- Name: nav_menu_items_enforce_depth(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nav_menu_items_enforce_depth() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  parent_of_parent uuid;
begin
  if new.parent_id is not null then
    select parent_id into parent_of_parent from public.nav_menu_items where id = new.parent_id;
    if parent_of_parent is not null then
      raise exception 'nav_menu_items only supports two levels — % is already a child item', new.parent_id;
    end if;
  end if;
  return new;
end;
$$;


