--
-- Name: pet_vaccination_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pet_vaccination_status AS
 SELECT DISTINCT ON (pet_id) pet_id,
    organization_id,
    id AS vaccination_id,
    vaccine_name,
    date_administered,
    next_due_date
   FROM public.vaccinations v
  WHERE (deleted_at IS NULL)
  ORDER BY pet_id, date_administered DESC, created_at DESC;


ALTER VIEW public.pet_vaccination_status OWNER TO postgres;

