--
-- Name: appointments appointments_select_lab; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY appointments_select_lab ON public.appointments FOR SELECT TO authenticated USING ((organization_id IN ( SELECT public.my_org_ids(ARRAY['lab'::text]) AS my_org_ids)));


--
-- Name: appointments appointments_select_reception; Type: POLICY; Schema: public; Owner: postgres
--

