CREATE POLICY avatars_select ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = 'avatars'::text) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR public.is_admin_of_user(((storage.foldername(name))[1])::uuid))));


--
-- Name: objects avatars_update; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY avatars_update ON storage.objects FOR UPDATE TO authenticated USING (((bucket_id = 'avatars'::text) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR public.is_admin_of_user(((storage.foldername(name))[1])::uuid)))) WITH CHECK (((bucket_id = 'avatars'::text) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR public.is_admin_of_user(((storage.foldername(name))[1])::uuid))));


